const today = new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().split('T')[0];
const queryBody = JSON.stringify({
  filter: {
    and: [
      { property: '有効', checkbox: { equals: true } },
      { property: '次回予定日', date: { on_or_before: today } }
    ]
  }
});
return [{ json: { requestBody: queryBody } }];

const results = $input.first().json.results || [];
if (results.length === 0) {
  return [{ json: { hasDue: false } }];
}
const items = results.map(page => {
  const titleEntry = Object.entries(page.properties).find(([k, v]) => v.type === 'title');
  const taskName = titleEntry ? titleEntry[1].title.map(t => t.plain_text).join('') : '(無題)';
  const frequency = page.properties['頻度']?.multi_select?.[0]?.name || 'monthly';
  const templateText = (page.properties['テンプレ本文']?.rich_text || []).map(t => t.plain_text).join('');
  const defPageId = page.id;
  return { json: { hasDue: true, defPageId, taskName, frequency, templateText } };
});
return items;

