  const body = {
    parent: { database_id: '2a02570f-e49f-802b-a67c-fe4c230a5699' },
    properties: {
      '': { title: [{ text: { content: d.taskName } }] },
      'ステータス': { status: { name: '未着手' } }
    },
    cover: { type: 'external', external: { url: coverUrl } }
  };
  if (d.templateText) {
    body.children = [{
      object: 'block',
      type: 'paragraph',
      paragraph: {
        rich_text: [{ type: 'text', text: { content: d.templateText } }]
      }
    }];
  }
  return { json: { ...d, requestBody: JSON.stringify(body) } };
});

const items = $input.all();
const originals = $('ParseDueTasks').all();
return items.map((item, i) => {
  const original = originals[i].json;
  const today = new Date(Date.now() + 9 * 60 * 60 * 1000).toISOString().split('T')[0];
  const nextDate = new Date();
  switch (original.frequency) {
    case 'daily': nextDate.setDate(nextDate.getDate() + 1); break;
    case 'every_3_days': nextDate.setDate(nextDate.getDate() + 3); break;
    case 'weekly': nextDate.setDate(nextDate.getDate() + 7); break;
    case 'biweekly': nextDate.setDate(nextDate.getDate() + 14); break;
    case 'monthly': nextDate.setMonth(nextDate.getMonth() + 1); break;
    default: nextDate.setMonth(nextDate.getMonth() + 1); break;
  }
  const nextDue = new Date(nextDate.getTime() + 9 * 60 * 60 * 1000).toISOString().split('T')[0];
  const body = {
    properties: {
      '最終実行日': { date: { start: today } },
      '次回予定日': { date: { start: nextDue } }
    }
  };
  return { json: { pageId: original.defPageId, taskName: original.taskName, requestBody: JSON.stringify(body) } };
});
